package middleware

import (
	"net/http"
	"net/http/httptest"
	"testing"

	"github.com/labstack/echo/v4"
)

func TestTmpProxyBalancerWithNoTargets(t *testing.T) {
	e := echo.New()
	balancers := []struct {
		name string
		b    ProxyBalancer
	}{
		{"random", NewRandomBalancer([]*ProxyTarget{})},
		{"roundRobin", NewRoundRobinBalancer([]*ProxyTarget{})},
	}
	for _, tc := range balancers {
		t.Run(tc.name, func(t *testing.T) {
			h := ProxyWithConfig(ProxyConfig{Balancer: tc.b})(func(c echo.Context) error {
				return nil
			})

			req := httptest.NewRequest(http.MethodGet, "/", nil)
			rec := httptest.NewRecorder()
			c := e.NewContext(req, rec)

			var err error
			func() {
				defer func() {
					if r := recover(); r != nil {
						t.Fatalf("handler panicked: %v", r)
					}
				}()
				err = h(c)
			}()

			if err == nil {
				t.Fatal("expected non-nil error, got nil")
			}
			he, ok := err.(*echo.HTTPError)
			if !ok {
				t.Fatalf("expected *echo.HTTPError, got %T: %v", err, err)
			}
			if he.Code != http.StatusServiceUnavailable {
				t.Fatalf("expected code %d, got %d", http.StatusServiceUnavailable, he.Code)
			}
		})
	}
}

