cat > /echo/zz_ref_tmp_test.go <<'EOF'
package echo

import (
	"math/rand"
	"net/http"
	"strings"
	"testing"
)

// reference matcher: does pattern match path (echo v4 semantics)?
func refMatch(pattern, path string) bool {
	if pattern == "" {
		pattern = "/"
	}
	if !strings.HasPrefix(pattern, "/") {
		pattern = "/" + pattern
	}
	ps := strings.Split(pattern, "/")
	xs := strings.Split(path, "/")
	var m func(i, j int) bool
	m = func(i, j int) bool {
		if i == len(ps) {
			return j == len(xs)
		}
		seg := ps[i]
		if seg == "*" {
			// matches remainder (may be empty) -> consumes all remaining segments
			return true
		}
		if j >= len(xs) {
			return false
		}
		if strings.HasPrefix(seg, ":") {
			return m(i+1, j+1)
		}
		if seg == xs[j] {
			return m(i+1, j+1)
		}
		return false
	}
	return m(0, 0)
}

func TestRefCompare(t *testing.T) {
	rand.Seed(3)
	bad := 0
	for iter := 0; iter < 4000; iter++ {
		e := New()
		n := 1 + rand.Intn(3)
		used := map[string]bool{}
		var routes []string
		for i := 0; i < n; i++ {
			p := fzPatterns[rand.Intn(len(fzPatterns))]
			if used[p] {
				continue
			}
			used[p] = true
			routes = append(routes, p)
			e.router.Add(http.MethodGet, p, func(c Context) error { return nil })
		}
		for _, path := range fzPaths {
			c := e.NewContext(nil, nil)
			e.router.Find(http.MethodGet, path, c)
			got := c.Path()
			expect := ""
			for _, rp := range routes {
				if refMatch(rp, path) {
					expect = rp
					break
				}
			}
			if (got == "") != (expect == "") {
				bad++
				if bad < 25 {
					t.Errorf("MISMATCH routes=%v path=%q got=%q ref=%q", routes, path, got, expect)
				}
			}
		}
	}
	t.Logf("total mismatches: %d", bad)
}
EOF
