func (c *context) Scheme() string {
	// Can't use `r.Request.URL.Scheme`
	// See: https://groups.google.com/forum/#!topic/golang-nuts/pMUkBlQBDF0
	if c.IsTLS() {
		return "https"
	}
	if scheme := normalizeScheme(c.request.Header.Get(HeaderXForwardedProto)); scheme != "" {
		return scheme
	}
	if scheme := normalizeScheme(c.request.Header.Get(HeaderXForwardedProtocol)); scheme != "" {
		return scheme
	}
	if ssl := c.request.Header.Get(HeaderXForwardedSsl); ssl == "on" {
		return "https"
	}
	if scheme := normalizeScheme(c.request.Header.Get(HeaderXUrlScheme)); scheme != "" {
		return scheme
	}
	return "http"
}

// normalizeScheme returns the normalized (lowercased, trimmed) value of the
// given scheme when it is a valid HTTP scheme ("http" or "https"). Any other
// value is considered invalid and an empty string is returned, so callers can
// ignore it and fall back to the next source of information.
func normalizeScheme(scheme string) string {
	scheme = strings.ToLower(strings.TrimSpace(scheme))
	if scheme == "http" || scheme == "https" {
		return scheme
	}
	return ""
}

