func TestTmpContextScheme(t *testing.T) {
	tests := []struct {
		name   string
		header http.Header
		tls    bool
		want   string
	}{
		{
			name:   "invalid X-Forwarded-Proto falls back to X-Forwarded-Protocol",
			header: http.Header{HeaderXForwardedProto: []string{"invalid"}, HeaderXForwardedProtocol: []string{"https"}},
			want:   "https",
		},
		{
			name:   "all forwarded headers invalid falls back to http",
			header: http.Header{HeaderXForwardedProto: []string{"invalid"}, HeaderXForwardedProtocol: []string{"invalid"}, HeaderXUrlScheme: []string{"invalid"}},
			want:   "http",
		},
		{
			name:   "valid X-Forwarded-Proto is used",
			header: http.Header{HeaderXForwardedProto: []string{"https"}},
			want:   "https",
		},
		{
			name:   "valid X-Forwarded-Proto http is used",
			header: http.Header{HeaderXForwardedProto: []string{"http"}},
			want:   "http",
		},
		{
			name:   "case and whitespace insensitive",
			header: http.Header{HeaderXForwardedProto: []string{" HTTPS "}},
			want:   "https",
		},
		{
			name:   "TLS",
			header: http.Header{},
			tls:    true,
			want:   "https",
		},
		{
			name:   "no headers",
			header: http.Header{},
			want:   "http",
		},
	}
	for _, tt := range tests {
		tt := tt
		t.Run(tt.name, func(t *testing.T) {
			req := &http.Request{Header: tt.header}
			if tt.tls {
				req.TLS = &tls.ConnectionState{}
			}
			c := &context{request: req}
			if got := c.Scheme(); got != tt.want {
				t.Errorf("Scheme() = %q, want %q", got, tt.want)
			}
		})
	}
}
