// returns the pattern that should win (echo priority: static > param > any, depth first)
func refBest(patterns []string, path string) string {
	best := ""
	var m func(ps, xs []string, i, j int) bool
	m = func(ps, xs []string, i, j int) bool {
		if i == len(ps) {
			return j == len(xs)
		}
		seg := ps[i]
		if seg == "*" {
			return j < len(xs)
		}
		if j >= len(xs) {
			return false
		}
		if strings.HasPrefix(seg, ":") {
			if xs[j] == "" {
				return false
			}
			return m(ps, xs, i+1, j+1)
		}
		if seg == xs[j] {
			return m(ps, xs, i+1, j+1)
		}
		return false
	}
	// choose by priority: compare segment by segment
	better := func(a, b string) bool {
		as := strings.Split(a, "/")
		bs := strings.Split(b, "/")
		for i := 0; i < len(as) && i < len(bs); i++ {
			rank := func(s string) int {
				if s == "*" {
					return 2
				}
				if strings.HasPrefix(s, ":") {
					return 1
				}
				return 0
			}
			if rank(as[i]) != rank(bs[i]) {
				return rank(as[i]) < rank(bs[i])
			}
		}
		return false
	}
	xs := strings.Split(path, "/")
	for _, p := range patterns {
		ps := strings.Split(p, "/")
		if !m(ps, xs, 0, 0) {
			continue
		}
		if best == "" || better(p, best) {
			best = p
		}
	}
	return best
}

