// lenient: params may match empty segments; '*' consumes the rest (needs at least the trailing empty segment)
func lenientMatch(pattern, path string) bool {
	if pattern == "" {
		pattern = "/"
	}
	if !strings.HasPrefix(pattern, "/") {
		pattern = "/" + pattern
	}
	ps := strings.Split(pattern, "/")
	xs := strings.Split(path, "/")
