		}
		seg := ps[i]
		if seg == "*" {
			return j < len(xs)
		}
		if j >= len(xs) {
			return false
		}
		if strings.HasPrefix(seg, ":") {
			return m(i+1, j+1)
		}
		if seg == xs[j] {
